CREATE OR REPLACE FUNCTION public.birdtie_memory_source_invalidated()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o uuid;kind text;epoch text;
BEGIN
 IF TG_TABLE_NAME='moments' THEN o:=OLD.author_account_id;kind:='MOMENT';epoch:=OLD.revision::text;
 ELSIF TG_TABLE_NAME='activity_participations' THEN o:=OLD.participant_account_id;kind:='ACTIVITY_PARTICIPATION';epoch:=OLD.updated_at::text;
 ELSE o:=OLD.owner_account_id;kind:='SAVED_PLACE';epoch:=OLD.created_at::text;END IF;
 IF EXISTS(SELECT 1 FROM accounts WHERE id=o) THEN INSERT INTO agent_memory_source_invalidations(owner_id,source_type,source_id,source_epoch) VALUES(o,kind,OLD.id,epoch);END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.birdtie_guard_close_connection()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE n timestamptz:=clock_timestamp();
BEGIN
 IF TG_OP='DELETE' THEN
  -- Only actual parent deletion may erase a source fence. Human revocation is
  -- an UPDATE; native fixture cleanup and FK cascades remain compatible.
  IF EXISTS(SELECT 1 FROM accounts WHERE id=OLD.owner_account_id) AND
     EXISTS(SELECT 1 FROM accounts WHERE id=OLD.person_account_id) AND
     EXISTS(SELECT 1 FROM person_ties WHERE id=OLD.tie_id) AND
     EXISTS(SELECT 1 FROM connection_requests WHERE id=OLD.request_id) THEN
   RAISE EXCEPTION 'close source fence cannot be erased' USING ERRCODE='23514';
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.native_revision<>1 THEN RAISE EXCEPTION 'initial close revision required' USING ERRCODE='23514'; END IF;
  NEW.created_at:=n;
 ELSE
  IF NEW.owner_account_id<>OLD.owner_account_id OR NEW.person_account_id<>OLD.person_account_id OR NEW.created_at<>OLD.created_at OR NEW.native_revision<>OLD.native_revision THEN
   RAISE EXCEPTION 'close owner and native revision are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.native_revision=9223372036854775807 THEN RAISE EXCEPTION 'close revision exhausted' USING ERRCODE='23514'; END IF;
  IF OLD.is_active AND NEW.is_active AND (NEW.tie_id<>OLD.tie_id OR NEW.request_id<>OLD.request_id) THEN
   RAISE EXCEPTION 'new friend source requires retired selection' USING ERRCODE='23514';
  END IF;
  NEW.native_revision:=OLD.native_revision+1;
 END IF;
 IF NEW.is_active THEN
  -- Protect an absent Block against a concurrent native INSERT. Original
  -- production writers acquire this lock before touching the Close row.
  LOCK TABLE account_blocks IN SHARE MODE;
  PERFORM id FROM person_ties WHERE id=NEW.tie_id FOR SHARE;
  IF NOT birdtie_connection_visible(NEW.owner_account_id,NEW.person_account_id) OR NOT EXISTS(
   SELECT 1 FROM person_ties t WHERE t.id=NEW.tie_id AND t.request_id=NEW.request_id AND t.status='active'
   AND t.person_a_account_id=LEAST(NEW.owner_account_id,NEW.person_account_id)
   AND t.person_b_account_id=GREATEST(NEW.owner_account_id,NEW.person_account_id)) THEN
   RAISE EXCEPTION 'close selection requires current accepted Friend source' USING ERRCODE='23514';
  END IF;
  NEW.selected_at:=clock_timestamp(); NEW.retired_at:=NULL;
 ELSE
  IF TG_OP='UPDATE' THEN NEW.selected_at:=OLD.selected_at; ELSE NEW.selected_at:=NULL; END IF;
  NEW.retired_at:=clock_timestamp();
 END IF;
 NEW.updated_at:=clock_timestamp(); RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.birdtie_entity_share_operation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'entity share history immutable' USING ERRCODE='23514';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.actor_account_id::text||':ENTITY_SHARE:'||NEW.operation_id::text,143));
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=NEW.actor_account_id AND account_type='person' AND status='active') THEN RAISE EXCEPTION 'share actor unavailable' USING ERRCODE='23514';END IF;
 IF NEW.status='STOPPED' THEN
  IF EXISTS(SELECT 1 FROM conversation_messages WHERE sender_account_id=NEW.actor_account_id AND client_operation_id=NEW.operation_id) THEN RAISE EXCEPTION 'existing message cannot be stopped' USING ERRCODE='23514';END IF;RETURN NEW;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM conversation_messages m JOIN conversations c ON c.id=m.conversation_id WHERE m.id=NEW.message_id AND m.conversation_id=NEW.conversation_id AND m.sender_account_id=NEW.actor_account_id AND m.client_operation_id=NEW.operation_id AND m.entity_type=NEW.entity_type AND m.entity_id=NEW.entity_id AND m.body='分享了一张卡片' AND m.speaker_kind='human' AND((NEW.recipient_type='CONVERSATION' AND NEW.recipient_id=c.id)OR(NEW.recipient_type='FRIEND_TIE' AND EXISTS(SELECT 1 FROM person_ties t WHERE t.id=NEW.recipient_id AND t.status='active'  AND t.person_a_account_id=LEAST(c.member_a_account_id,c.member_b_account_id) AND t.person_b_account_id=GREATEST(c.member_a_account_id,c.member_b_account_id))))) THEN RAISE EXCEPTION 'share receipt requires exact native effect' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.birdtie_guard_human_moment_public_control()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable Moment operation';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.actor_account_id::text||':MOMENT:'||NEW.operation_id::text,144));
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=NEW.actor_account_id AND account_type='person' AND status='active') THEN RAISE EXCEPTION 'current Person required';END IF;
 IF NEW.status='SUCCEEDED' AND NOT EXISTS(SELECT 1 FROM moments m WHERE m.id=NEW.moment_id AND m.author_account_id=NEW.actor_account_id AND m.revision=NEW.applied_revision AND((NEW.action IN('CREATE','UPDATE') AND m.status='draft' AND m.visibility='private') OR(NEW.action='WITHDRAW' AND m.status='withdrawn' AND m.visibility='private') OR(NEW.action IN('PUBLISH','UPDATE_PUBLIC') AND m.status='published' AND m.visibility='public' AND ((m.place_id IS NOT NULL AND m.location_precision='place') OR(m.place_id IS NULL AND m.location_precision IN('none','city'))) AND m.author_confirmed_at IS NOT NULL AND m.published_at IS NOT NULL AND m.author_confirmed_at<=m.published_at))) THEN RAISE EXCEPTION 'canonical owned Moment effect required';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.birdtie_guard_moment_media_receipt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'original media operation receipts are immutable';END IF;
 IF NEW.receipt->>'operationId'<>NEW.operation_id::text THEN RAISE EXCEPTION 'original media operation identity required';END IF;
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=NEW.actor_account_id AND account_type='person' AND status='active') THEN RAISE EXCEPTION 'current person required';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.birdtie_guard_moment_thread()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'thread identity is retained';END IF;
 IF TG_OP='INSERT' AND NEW.audience='PRIVATE' THEN
 IF NEW.status<>'draft' OR NEW.version<>1 OR NOT EXISTS(SELECT 1 FROM legacy_native_context_entities x JOIN accounts a ON a.id=x.owner_account_id AND a.account_type='person' AND a.status IN('active','suspended') WHERE x.kind='thread' AND x.target_id=NEW.id AND x.owner_account_id=NEW.author_account_id)THEN RAISE EXCEPTION 'private original import provenance required';END IF;RETURN NEW;END IF;
 IF TG_OP='UPDATE' THEN
 IF NEW.id<>OLD.id OR NEW.author_account_id<>OLD.author_account_id OR NEW.root_moment_id<>OLD.root_moment_id OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'stable original thread required';END IF;
 IF EXISTS(SELECT 1 FROM moment_thread_edit_states e WHERE e.thread_id=OLD.id AND e.version=NEW.version) THEN
 IF NEW.audience<>'PUBLIC' OR NEW.status NOT IN('published','withdrawn') THEN RAISE EXCEPTION 'explicit public editing state required';END IF;
 IF NEW.status='withdrawn' AND EXISTS(SELECT 1 FROM moment_thread_members x JOIN moments m ON m.id=x.moment_id WHERE x.thread_id=OLD.id AND m.status<>'withdrawn') THEN RAISE EXCEPTION 'all children must withdraw';END IF;
 ELSIF OLD.audience='PRIVATE'  AND OLD.status='draft' AND NEW.audience='PUBLIC' AND NEW.status='published' THEN
 IF(SELECT count(*)FROM moment_thread_members WHERE thread_id=OLD.id)NOT BETWEEN 2 AND 20 OR EXISTS(SELECT 1 FROM moment_thread_members x JOIN moments m ON m.id=x.moment_id WHERE x.thread_id=OLD.id AND(m.status<>'published' OR m.visibility<>'public' OR m.author_account_id<>OLD.author_account_id))THEN RAISE EXCEPTION 'all original children must publish atomically';END IF;
 ELSIF OLD.audience<>'PUBLIC' OR OLD.status<>'published' OR NEW.audience<>'PUBLIC' OR NEW.status<>'withdrawn' OR EXISTS(SELECT 1 FROM moment_thread_members x JOIN moments m ON m.id=x.moment_id WHERE x.thread_id=OLD.id AND m.status<>'withdrawn')THEN RAISE EXCEPTION 'exact whole-thread transition required';END IF;END IF;
 IF NOT EXISTS(SELECT 1 FROM accounts WHERE id=NEW.author_account_id AND account_type='person' AND status='active')THEN RAISE EXCEPTION 'active Person required';END IF;RETURN NEW;END$function$
